-- Widow Jane import (bourbon.widow_jane), applied 2026-09-24 via the Supabase MCP. No hand steps.
-- Also fixed catalog/bourbon/normalize.py:spirit_type(): a second instance of the same bug class as the Bardstown fix. The exclusion for non-whiskey spirits (vodka, gin, tequila, rum, brandy...) checked the combined class+name text, so Widow Jane's 'Tequila Ocho Cask Finish' bourbon (a cask pedigree in the marketing name, not the class) was being skipped as not-whiskey. Now checks class_raw alone. Verified no regression across all 14 previously-applied sources.

update cellar.products set proof = 91.0, image_url = coalesce(image_url, 'https://widowjane.com/wp-content/uploads/2024/05/ZkwW5Col0Zci9TYZ_babyjanewebsitebottle.png'), producer = coalesce(producer, 'Widow Jane'), producer_id = coalesce(producer_id, '3d5b0c8a-58e3-4ea1-961c-5d68f087cbb1'::uuid), source = 'maker', source_url = 'https://widowjane.com/whiskey/baby-jane-bourbon/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '755941ae-3d37-4a6f-845a-342cde6caf85' and facts_verified_at is null;
update cellar.products set image_url = coalesce(image_url, 'https://widowjane.com/wp-content/uploads/2026/04/Black-Opal-Website-4.png'), name = 'Widow Jane Black Opal', expression = 'Black Opal', aliases = (select array_agg(distinct a) from unnest(array_append(aliases, 'Widow Jane Black Opal 20 Year')) a), producer = coalesce(producer, 'Widow Jane'), producer_id = coalesce(producer_id, '3d5b0c8a-58e3-4ea1-961c-5d68f087cbb1'::uuid), source = 'maker', source_url = 'https://widowjane.com/whiskey/black-opal/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = 'cf491863-8ad5-49a8-a158-7e136c278bd2' and facts_verified_at is null;
