update cellar.products set source_checked_at = now() where id in ('40b99e37-712b-47b7-aec7-05426bf92072', '67723a6b-095c-43bc-ae73-407f8bda4b0d', '0e1f7ba0-031f-475c-ab74-8093a9aec03a', '755941ae-3d37-4a6f-845a-342cde6caf85', 'cf491863-8ad5-49a8-a158-7e136c278bd2', 'd89f92fb-60cd-4162-bc98-8d96485ec7d7', 'c11bb240-afa8-4325-858a-9b99681a5815');
update cellar.products set source = 'maker', source_url = 'https://widowjane.com/whiskey/10-year-bourbon/', discontinued = false, catalog_included = catalog_included or is_core_range, producer = coalesce(producer, 'Widow Jane'), producer_id = coalesce(producer_id, '3d5b0c8a-58e3-4ea1-961c-5d68f087cbb1'::uuid), image_url = coalesce(image_url, 'https://widowjane.com/wp-content/uploads/2024/05/acf3aac8-a089-40d7-a806-08df8ae24c75_WJ10Website.png') where id = '40b99e37-712b-47b7-aec7-05426bf92072' and facts_verified_at is null;
