insert into cellar.product_images (product_id, image_url, is_hero) select p.id, p.image_url, true from cellar.products p where p.type = 'bourbon' and p.source = 'maker' and p.image_url like 'https://widowjane.com/%' and not exists (select 1 from cellar.product_images i where i.product_id = p.id);
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', '{}'::jsonb, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), r.img, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Widow Jane Apple Wood Aged Rye","rar":"allocated","f":"Widow Jane","x":"Apple Wood Aged Rye","p":93.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"rye","mb":null,"st":"rye","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://widowjane.com/wp-content/uploads/2024/05/277d7e8a-51c9-4539-8843-7b97ed9db53b_APPLEWOODRYEWEBSITE.png","u":"https://widowjane.com/whiskey/apple-wood-aged-rye/","pr":"Widow Jane","mk":"3d5b0c8a-58e3-4ea1-961c-5d68f087cbb1"},{"n":"Widow Jane Borough Blend","rar":"lottery","f":"Widow Jane","x":"Borough Blend","p":91.0,"ay":10.0,"al":"10 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":["Widow Jane 10 Year Borough Blend"],"img":"https://widowjane.com/wp-content/uploads/2026/05/Borough-Blend-website.png","u":"https://widowjane.com/whiskey/borough-blend/","pr":"Widow Jane","mk":"3d5b0c8a-58e3-4ea1-961c-5d68f087cbb1"},{"n":"Widow Jane Tequila Ocho Cask Finish","rar":"lottery","f":"Widow Jane","x":"Tequila Ocho Cask Finish","p":91.0,"ay":10.0,"al":"10 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":"Tequila Ocho Cask Finish","msrp":null,"core":false,"al2":[],"img":"https://widowjane.com/wp-content/uploads/2026/05/WJT8bottlesm.png","u":"https://widowjane.com/whiskey/tequila-ocho-cask-finish/","pr":"Widow Jane","mk":"3d5b0c8a-58e3-4ea1-961c-5d68f087cbb1"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');